// Command IncidentIo-cli is a CLI + REPL for the IncidentIo SDK,
// built on the boru engine. Positional arguments are joined into a
// single boru expression and evaluated; with no arguments, falls into
// a REPL. Generated by sdkgen go-cli target.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	eng "github.com/boru-lang/boru/eng/go"
	"github.com/boru-lang/boru/eng/go/parser"
	sdk "github.com/voxgig-sdk/incident-io-sdk/go"
)

// prompt is the REPL prompt prefix (matches the SDK slug).
const prompt = "incident-io"

// entitiesHelp is the space-separated entity list shown by /help.
const entitiesHelp = "action alert alert_attribute alert_note alert_route alert_source alert_sources_v2 alert_tag alerts_add_tags_result_v2 alerts_remove_tags_result_v2 alerts_set_tags_result_v2 alerts_transition_incident_alert_result_v2 announcement_rule announcement_template api_key call_route call_routes_create_allowed_caller_result_v2 call_routes_create_option_result_v2 call_routes_list_allowed_callers_result_v2 call_routes_list_options_result_v2 call_routes_show_allowed_caller_result_v2 call_routes_show_option_result_v2 call_routes_update_allowed_caller_result_v2 call_routes_update_option_result_v2 call_routes_v2 call_session call_transcript_entry catalog_entry catalog_resource catalog_type catalog_type_schema custom_field custom_field_option escalation escalation_path_template escalations_check_escalation_permissions_result_v2 escalations_reassign_escalation_result_v2 follow_up follow_ups_connect_external_issue_result_v3 follow_ups_create_from_link_result_v3 identity incident incident_activity_log_entry incident_attachment incident_form incident_membership incident_participant incident_participant_workload incident_relationship incident_role incident_status incident_team_membership incident_team_memberships_v1 incident_template incident_templates_validate_result_v1 incident_timeline_item incident_timestamp incident_type incident_update ip_allowlist ip_range maintenance_window managed_resource on_call_notification_method_public_v2 on_call_notification_pause on_call_notification_rule_public_v2 pay_config pay_configs_create_one_off_rule_result_v2 pay_configs_create_weekly_rule_result_v2 pay_configs_list_one_off_rules_result_v2 pay_configs_list_weekly_rules_result_v2 pay_configs_show_one_off_rule_result_v2 pay_configs_show_weekly_rule_result_v2 pay_configs_update_one_off_rule_result_v2 pay_configs_update_weekly_rule_result_v2 pay_configs_v2 pay_report pay_reports_publish_result_v2 pay_reports_unpublish_result_v2 pay_reports_v2 policies_v2 policy policy_finding policy_findings_dismiss_result_v2 policy_findings_restore_result_v2 postmortem_document schedule schedule_entries_list_payload_v2 schedule_entry schedule_replica schedule_sync_rule schedule_sync_target schedules_show_override_result_v2 schedules_update_override_result_v2 secret severity status_page status_page_component status_page_component_availability_v2 status_page_incident status_page_incident_update status_page_linked_response_incident_v1 status_page_maintenance status_page_maintenance_update status_page_structure status_pages_v2 team telemetry_data_source_v2 user workflow workflow_run"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — boru-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<boru expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single boru expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      INCIDENT_IO_APIKEY (api key), INCIDENT_IO_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: INCIDENT_IO_APIKEY carries the API key and
	// INCIDENT_IO_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("INCIDENT_IO_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("INCIDENT_IO_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewIncidentIoSDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
